/* InsightBase slide editor. Session only; never stores workbook data. */
(function(root){
'use strict';
const E=root.FinoraEngine,colors=['245DE8','21A59A','7999EF','E2A54D','915DC7','CB627B'],groups={Sektör:'Sektör',Ozel:'Özel',Kamu:'Kamu'},modes={nominal:'Hacim / oran',change:'MoM',yoyChange:'YoY',ytdChange:'YTD'},nf=new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2});
function downloadName(extension,date=new Date()){const pad=n=>String(n).padStart(2,'0');return `InsightBase-Sunum_${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}_${pad(date.getHours())}-${pad(date.getMinutes())}-${pad(date.getSeconds())}.${extension}`;}
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ratio=(t,r)=>root.TEMPLATE?.[t]?.rows.find(x=>x.row===r)?.ratio??(t==='BS'?r===57:[29,30,31,32,45,67,68,69,70,83].includes(r)),monthText=d=>new Date(d+'T00:00:00Z').toLocaleDateString('tr-TR',{month:'short',year:'2-digit',timeZone:'UTC'});
let ctx,slides=[],selected=0,widgetIndex=0,serial=0,busy=false,message='';
const periods=(start,end)=>{const out=[];if(!/^\d{4}-\d{2}$/.test(start)||!/^\d{4}-\d{2}$/.test(end)||start>end)return out;let d=new Date(start+'-01T00:00:00Z');while(d.toISOString().slice(0,7)<=end&&out.length<120){out.push(E.monthEnd(d.getUTCFullYear(),d.getUTCMonth()));d.setUTCMonth(d.getUTCMonth()+1);}return out;};
function latest(type){return ctx.dataset.sheets.filter(s=>s.type===type).flatMap(s=>s.dates.filter((d,i)=>s.rows.some(r=>E.finite(r.values[i])))).sort().at(-1)||new Date().toISOString().slice(0,10);}
function widget(type='BS'){const last=latest(type),anchor=new Date(last+'T00:00:00Z');if(type==='BS'&&last!==E.monthEnd(anchor.getUTCFullYear(),anchor.getUTCMonth()))anchor.setUTCDate(0);const end=anchor.toISOString().slice(0,7),d=new Date(end+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()-5);return {id:++serial,title:type==='BS'?'Kredi gelişimi':'Net kâr gelişimi',type,kind:'line',rows:[type==='BS'?3:65],groups:['Sektör'],mode:'change',start:d.toISOString().slice(0,7),end,unit:1000,table:false,tableRows:[type==='BS'?3:65],tableGroups:['Sektör'],tableModes:['nominal','change','yoyChange']};}
function newSlide(){return {id:++serial,title:'Sektör görünümü',layout:'single',comment:'',source:'Kaynak: dataa.xlsx',note:'',widgets:[widget()]};}
function points(dataset,type,row,group,start,end,mode='nominal',unit=1000){const sh=dataset.sheets.find(s=>s.type===type&&s.group===group),s=E.metricSeries(sh,row),cu=E.metricSeries(sh,type==='PL'&&row>=49?row-38:row),r=ratio(type,row);return periods(start,end).map(date=>{const c=E.at(s,date,type==='BS'?7:32);if(!c||c.date.slice(0,7)!==date.slice(0,7))return {date,value:null,sourceDate:null};const m=E.compare(s,c.date,type,r,type==='PL'&&row>=11&&row<=45),cm=E.compare(cu,c.date,type,r,true);if(type==='BS'){const d=new Date(date+'T00:00:00Z'),y=d.getUTCFullYear(),mo=d.getUTCMonth(),delta=b=>!b?null:r?c.value-b.value:E.pct(c.value,b.value);m.prior=E.at(s,E.monthEnd(y,mo-1),7);m.yoy=E.at(s,E.monthEnd(y-1,mo),7);m.ytd=E.at(s,E.monthEnd(y-1,11),7);m.change=delta(m.prior);m.yoyChange=delta(m.yoy);m.ytdChange=delta(m.ytd);}return {date,sourceDate:c.date,baseDate:mode==='change'?m.prior?.date:mode==='yoyChange'?m.yoy?.date:mode==='ytdChange'?(type==='BS'?m.ytd?.date:cm.yoy?.date):null,value:mode==='nominal'?(r?c.value:c.value/unit):mode==='ytdChange'?(type==='BS'?m.ytdChange:(cm.current?.date.slice(0,7)===date.slice(0,7)?cm.yoyChange:null)):m[mode]??null};});}
function series(w,rows=w.rows,gs=w.groups,mode=w.mode){return rows.flatMap(row=>gs.map(group=>({name:ctx.label(w.type,row)+' · '+groups[group]+' · '+(ratio(w.type,row)?'%':currency(w.type,row)),row,group,ratio:ratio(w.type,row),points:points(ctx.dataset,w.type,row,group,w.start,w.end,mode,w.unit)})));}
const currency=(t,r)=>root.TEMPLATE?.[t]?.rows.find(x=>x.row===r)?.format==='USD'?'USD':'TL';
function suffix(w,mode=w.mode,r=false,row=w.rows[0]){return mode==='nominal'?(r?'%':(w.unit===1?'mn ':w.unit===1000?'mlr ':'trln ')+currency(w.type,row)):r?'puan':'%';}
function format(v){return E.finite(v)?nf.format(v):'—';}
function tableData(w){const ss=series(w,w.tableRows,w.tableGroups),dates=periods(w.start,w.end),rows=w.tableRows.flatMap(row=>w.tableGroups.flatMap(g=>w.tableModes.map(mode=>({name:ctx.label(w.type,row)+' · '+groups[g]+' · '+(mode==='ytdChange'&&w.type==='PL'?'YTD YoY':modes[mode])+' ('+suffix(w,mode,ratio(w.type,row),row)+')',values:points(ctx.dataset,w.type,row,g,w.start,w.end,mode,w.unit).map(p=>format(p.value))}))));return {header:['Kalem / ölçüm',...dates.map(monthText)],rows:rows.map(r=>[r.name,...r.values])};}
function problems(w){const ss=series(w),dates=periods(w.start,w.end),errors=[];if((w.mode==='nominal'||w.kind==='pie')&&new Set(w.rows.filter(r=>!ratio(w.type,r)).map(r=>currency(w.type,r))).size>1)errors.push('TL ve USD nominal serileri aynı grafikte kullanılamaz; ayrı grafik seçin.');if(!dates.length)errors.push('Geçerli bir başlangıç ve bitiş ayı seçin.');if(dates.length>24)errors.push('Grafik başına en fazla 24 ay seçin.');if(!w.rows.length||!w.groups.length)errors.push('En az bir kalem ve banka grubu seçin.');if(ss.length>6)errors.push('Grafik başına en fazla 6 seri seçin.');if(w.rows.some(r=>ratio(w.type,r))&&w.rows.some(r=>!ratio(w.type,r)))errors.push('Oran ve tutar kalemlerini ayrı grafiklerde gösterin.');if(ss.length&&!ss.some(s=>s.points.some(p=>E.finite(p.value))))errors.push('Bu seçim için geçerli veri bulunmuyor.');if(w.kind==='pie'){const vals=ss.map(s=>s.points.at(-1)?.value);if(w.mode!=='nominal')errors.push('Pasta grafik yalnızca nominal dağılım için kullanılabilir.');if(vals.some(v=>!E.finite(v)||v<0)||!vals.some(v=>v>0))errors.push('Pasta için son ayda tüm değerler mevcut, negatif olmayan ve toplam pozitif olmalı.');const ds=ss.map(s=>s.points.at(-1)?.sourceDate);if(new Set(ds).size>1)errors.push('Pasta dilimleri aynı kaynak tarihinden gelmeli.');}
if(w.table){if(!w.tableRows.length||!w.tableGroups.length||!w.tableModes.length)errors.push('Alt tablo için kalem, grup ve ölçüm seçin.');if(dates.length>12)errors.push('Alt tablo için en fazla 12 ay seçin.');if(w.tableRows.length*w.tableGroups.length*w.tableModes.length>12)errors.push('Alt tablo en fazla 12 satır içerebilir.');}return errors;}
function visual(w){const ss=series(w),errors=problems(w);if(errors.length)return `<div class="deck-empty">${errors.map(safe).join('<br>')}</div>`;let svg='<svg viewBox="0 0 640 270" class="deck-chart" role="img" aria-label="'+safe(w.title)+'">';if(w.kind==='pie'){const vals=ss.map(s=>s.points.at(-1).value),sum=vals.reduce((a,b)=>a+b,0);let a=-Math.PI/2;ss.forEach((s,i)=>{const share=vals[i]/sum,b=a+share*2*Math.PI,x=150+90*Math.cos(a),y=135+90*Math.sin(a),xx=150+90*Math.cos(b),yy=135+90*Math.sin(b);svg+=share>=.999999?`<circle cx="150" cy="135" r="90" fill="#${colors[i]}"/>`:`<path d="M150,135 L${x},${y} A90,90 0 ${share>.5?1:0},1 ${xx},${yy} Z" fill="#${colors[i]}" stroke="white"/>`;svg+=`<text x="${150+62*Math.cos((a+b)/2)}" y="${135+62*Math.sin((a+b)/2)}" text-anchor="middle" fill="white" font-size="13">${format(share*100)}%</text>`;a=b;});}else {const vals=ss.flatMap(s=>s.points.map(p=>p.value)).filter(E.finite),lo=Math.min(0,...vals),hi=Math.max(0,...vals),range=hi-lo||1,n=ss[0].points.length,y=v=>220-(v-lo)/range*170,x=i=>60+(i+.5)*540/n;for(let i=0;i<4;i++){const v=lo+range*i/3;svg+=w.kind==='bar'?`<line x1="${60+(v-lo)/range*530}" y1="40" x2="${60+(v-lo)/range*530}" y2="220" stroke="#e5eaf2"/><text x="${60+(v-lo)/range*530}" y="235" text-anchor="middle" fill="#66758b" font-size="10">${format(v)}</text>`:`<line x1="55" y1="${y(v)}" x2="610" y2="${y(v)}" stroke="#e5eaf2"/><text x="48" y="${y(v)+4}" text-anchor="end" fill="#66758b" font-size="10">${format(v)}</text>`;}ss.forEach((s,k)=>{let path='',open=false;s.points.forEach((p,i)=>{if(!E.finite(p.value)){open=false;return;}if(w.kind==='line'){path+=`${open?'L':'M'}${x(i)},${y(p.value)} `;svg+=`<circle cx="${x(i)}" cy="${y(p.value)}" r="3" fill="#${colors[k]}"/><text x="${x(i)}" y="${y(p.value)-8-k*9}" text-anchor="middle" fill="#${colors[k]}" font-size="10">${format(p.value)}</text>`;open=true;}else if(w.kind==='bar'){const h=170/n/ss.length,yy=45+i*170/n+k*h;svg+=`<rect x="${60+(Math.min(0,p.value)-lo)/range*530}" y="${yy}" width="${Math.abs(p.value)/range*530}" height="${h*.8}" fill="#${colors[k]}"/><text x="${60+(p.value-lo)/range*530+4}" y="${yy+h*.6}" font-size="9" fill="#${colors[k]}">${format(p.value)}</text>`;}else{const bw=540/n/(ss.length+1);svg+=`<rect x="${x(i)-540/n/2+k*bw}" y="${Math.min(y(p.value),y(0))}" width="${bw*.85}" height="${Math.max(.5,Math.abs(y(p.value)-y(0)))}" fill="#${colors[k]}"/><text x="${x(i)-540/n/2+k*bw+bw*.4}" y="${y(p.value)-5}" text-anchor="middle" font-size="9" fill="#${colors[k]}">${format(p.value)}</text>`;}});if(w.kind==='line')svg+=`<path d="${path}" fill="none" stroke="#${colors[k]}" stroke-width="2.5"/>`;});ss[0].points.forEach((p,i)=>{if(w.kind==='bar')svg+=`<text x="52" y="${51+i*170/n}" text-anchor="end" font-size="9">${safe(monthText(p.date))}</text>`;else svg+=`<text x="${x(i)}" y="247" text-anchor="middle" font-size="9" fill="#66758b">${safe(monthText(p.date))}</text>`;});}svg+='</svg>';return svg+`<div class="deck-legend">${ss.map((s,i)=>`<span><i style="background:#${colors[i]}"></i>${safe(s.name)}</span>`).join('')}</div>`;}
function widgetPreview(w){const td=w.table?tableData(w):null;return `<div class="deck-widget ${w.table?'has-table':''}"><h4>${safe(w.title)}</h4><div class="deck-measure">${safe(w.mode==='ytdChange'&&w.type==='PL'?'YTD YoY':modes[w.mode])} · ${suffix(w,w.mode,ratio(w.type,w.rows[0]))} · ${w.start} — ${w.end}${w.kind==='pie'?' · Son ay dağılımı':''}</div>${visual(w)}${td?`<div class="deck-table"><table><thead><tr>${td.header.map(v=>`<th>${safe(v)}</th>`).join('')}</tr></thead><tbody>${td.rows.map(r=>`<tr>${r.map(v=>`<td>${safe(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</div>`;}
function preview(s){return `<div class="deck-slide"><div class="deck-slide-heading"><span>Insight<span>Base</span></span><h2>${safe(s.title)}</h2></div><div class="deck-slide-content ${s.layout}">${s.widgets.map(widgetPreview).join('')}</div><div class="deck-slide-comment">${safe(s.comment)}</div><div class="deck-slide-footer"><span>${ctx.dataset.demo?'DEMO · Sentetik veri · ':''}${safe(s.source)}${s.note?' · '+safe(s.note):''}</span><span>${selected+1}</span></div></div>`;}
const options=(items,value)=>items.map(([k,v])=>`<option value="${k}" ${String(value)===String(k)?'selected':''}>${safe(v)}</option>`).join('');
function checks(field,items,values){return `<div class="deck-checks">${items.map(([v,t])=>`<label><input type="checkbox" data-deck-check="${field}" value="${v}" ${values.map(String).includes(String(v))?'checked':''}>${safe(t)}</label>`).join('')}</div>`;}
function metricOptions(type){return ctx.template[type].rows.filter(r=>type==='BS'||r.row>=49).map(r=>[r.row,ctx.label(type,r.row)]);}
function render(context){ctx=context;if(!slides.length)slides=[newSlide()];selected=Math.min(selected,slides.length-1);const s=slides[selected];widgetIndex=Math.min(widgetIndex,s.widgets.length-1);const w=s.widgets[widgetIndex];return `<div class="deck-toolbar"><div><strong>Sunum çalışma alanı</strong><p>16:9 · Her grafik için bağımsız seçim · Oturum boyunca düzenlenir</p></div><div><button class="button" data-deck-action="add">+ Slayt ekle</button> <button class="button primary" data-deck-action="export" ${busy||context.loadState!=='ready'?'disabled':''}>${busy==='pptx'?'PowerPoint hazırlanıyor…':'PowerPoint indir'}</button> <button class="button" data-deck-action="pdf" ${busy||context.loadState!=='ready'?'disabled':''}>${busy==='pdf'?'PDF hazırlanıyor…':'PDF indir'}</button></div></div>${message?`<div class="notice" role="status">${safe(message)}</div>`:''}<div class="deck-editor"><aside class="deck-pages">${slides.map((p,i)=>`<button data-deck-slide="${i}" class="${i===selected?'active':''}"><span>${i+1}</span><strong>${safe(p.title||'Başlıksız slayt')}</strong><small>${p.layout==='single'?'Tek grafik':'İki grafik'}</small></button>`).join('')}<div class="deck-page-actions"><button data-deck-action="duplicate">Kopyala</button><button data-deck-action="up">↑</button><button data-deck-action="down">↓</button><button data-deck-action="delete">Sil</button></div></aside><div class="deck-workspace">${preview(s)}</div><aside class="deck-settings"><h3>Slayt ayarları</h3><label>Başlık<input data-deck-slide-field="title" maxlength="100" value="${safe(s.title)}"></label><label>Yerleşim<select data-deck-slide-field="layout">${options([['single','Tek grafik / grafik + alt tablo'],['double','Yan yana iki grafik']],s.layout)}</select></label><label>Yorum<textarea data-deck-slide-field="comment" maxlength="400">${safe(s.comment)}</textarea></label><label>Kaynak<input data-deck-slide-field="source" maxlength="160" value="${safe(s.source)}"></label><label>Dipnot<input data-deck-slide-field="note" maxlength="200" value="${safe(s.note)}"></label><div class="segmented">${s.widgets.map((v,i)=>`<button data-deck-widget="${i}" class="${i===widgetIndex?'selected':''}">Grafik ${i+1}</button>`).join('')}</div><h3>Grafik ${widgetIndex+1}</h3><label>Grafik başlığı<input data-deck-field="title" maxlength="100" value="${safe(w.title)}"></label><div class="deck-fields"><label>Veri<select data-deck-field="type">${options([['BS','Bilanço'],['PL','P&L']],w.type)}</select></label><label>Grafik türü<select data-deck-field="kind">${options([['line','Çizgi'],['column','Sütun'],['bar','Yatay çubuk'],['pie','Pasta']],w.kind)}</select></label></div><label>Ölçüm<select data-deck-field="mode">${options(Object.entries(modes).map(([k,v])=>[k,k==='ytdChange'&&w.type==='PL'?'YTD YoY':v]),w.mode)}</select></label><label>Görüntüleme birimi<select data-deck-field="unit">${options([[1,'Milyon'],[1000,'Milyar'],[1000000,'Trilyon']],w.unit)}</select></label><div class="deck-fields"><label>Başlangıç<input type="month" data-deck-field="start" value="${w.start}"></label><label>Bitiş<input type="month" data-deck-field="end" value="${w.end}"></label></div><h4>Kalemler</h4>${checks('rows',metricOptions(w.type),w.rows)}<h4>Banka grupları</h4>${checks('groups',Object.entries(groups),w.groups)}<label class="deck-toggle"><input type="checkbox" data-deck-field="table" ${w.table?'checked':''}>Grafik altında tablo</label>${w.table?`<h4>Tablo kalemleri</h4>${checks('tableRows',metricOptions(w.type),w.tableRows)}<h4>Tablo grupları</h4>${checks('tableGroups',Object.entries(groups),w.tableGroups)}<h4>Tablo ölçümleri</h4>${checks('tableModes',Object.entries(modes).map(([k,v])=>[k,k==='ytdChange'&&w.type==='PL'?'YTD YoY':v]),w.tableModes)}`:''}<p class="muted">BS: ay sonundaki son haftalık gözlem (en fazla 7 gün geriye). MoM ve YoY aynı ay sonu bazlarıyla hesaplanır. P&L: kaynak ay sonu. Pasta: bitiş ayındaki dağılım. Eksik değerler “—”; sıfırla doldurulmaz.</p></aside></div>`;}
function change(e,rerender){const t=e.target,s=slides[selected],w=s?.widgets[widgetIndex];if(!w)return;message='';if(t.dataset.deckSlideField){const key=t.dataset.deckSlideField;s[key]=t.value;if(key==='layout'){if(t.value==='double'&&s.widgets.length===1)s.widgets.push(widget('PL'));if(t.value==='single')s.widgets=s.widgets.slice(0,1);}rerender();return;}if(t.dataset.deckField){const key=t.dataset.deckField;w[key]=key==='table'?t.checked:key==='unit'?Number(t.value):t.value;if(key==='type'){const fresh=widget(w.type);w.rows=fresh.rows;w.tableRows=fresh.tableRows;w.start=fresh.start;w.end=fresh.end;}if(key==='kind'&&w.kind==='pie')w.mode='nominal';rerender();return;}if(t.dataset.deckCheck){const key=t.dataset.deckCheck,val=['rows','tableRows'].includes(key)?Number(t.value):t.value;w[key]=t.checked?[...w[key],val]:w[key].filter(v=>v!==val);rerender();}}
async function click(e,rerender){const t=e.target.closest('[data-deck-action],[data-deck-slide],[data-deck-widget]');if(!t)return;message='';if(t.dataset.deckSlide!==undefined){selected=Number(t.dataset.deckSlide);widgetIndex=0;}if(t.dataset.deckWidget!==undefined)widgetIndex=Number(t.dataset.deckWidget);switch(t.dataset.deckAction){case 'add':slides.push(newSlide());selected=slides.length-1;widgetIndex=0;break;case 'duplicate':slides.splice(selected+1,0,JSON.parse(JSON.stringify(slides[selected])));selected++;break;case 'delete':if(slides.length>1){slides.splice(selected,1);selected=Math.max(0,selected-1);}else message='En az bir slayt kalmalı.';break;case 'up':if(selected>0){[slides[selected],slides[selected-1]]=[slides[selected-1],slides[selected]];selected--;}break;case 'down':if(selected<slides.length-1){[slides[selected],slides[selected+1]]=[slides[selected+1],slides[selected]];selected++;}break;case 'export':await exportDeck(rerender);return;case 'pdf':await exportPDF(rerender);return;}rerender();}
async function exportDeck(rerender){const all=slides.flatMap((s,i)=>s.widgets.flatMap((w,j)=>problems(w).map(p=>`Slayt ${i+1}, grafik ${j+1}: ${p}`)));if(all.length){message=all.join(' ');rerender();return;}busy='pptx';message='';rerender();try{const ppt=new root.pptxgen();ppt.layout='LAYOUT_WIDE';ppt.author='InsightBase';ppt.subject='Bankacılık sektör analizi';ppt.title='InsightBase';ppt.company='InsightBase';ppt.lang='tr-TR';ppt.theme={headFontFace:'Arial',bodyFontFace:'Arial',lang:'tr-TR'};slides.forEach((s,index)=>{const sl=ppt.addSlide();sl.background={color:'FFFFFF'};sl.addShape(ppt.ShapeType.rect,{x:.45,y:.45,w:.07,h:.7,fill:{color:'245DE8'},line:{color:'245DE8'}});sl.addText(s.title||'Sektör görünümü',{x:.7,y:.42,w:10.8,h:.52,fontSize:25,bold:true,color:'17243B',margin:0,breakLine:false});sl.addText('InsightBase',{x:11.45,y:.45,w:1.4,h:.3,fontSize:13,color:'245DE8',bold:true,margin:0});s.widgets.forEach((w,j)=>{const dual=s.layout==='double',x=dual?.65+j*6.15:.65,width=dual?5.85:12.05,has=w.table,chartY=1.57,chartH=has?2.45:4.4,ss=series(w),unit=suffix(w,w.mode,ss[0].ratio);sl.addText(w.title,{x,y:1.08,w:width,h:.27,fontSize:16,bold:true,color:'17243B',margin:0});sl.addText(`${w.mode==='ytdChange'&&w.type==='PL'?'YTD YoY':modes[w.mode]} · ${unit} · ${w.start} — ${w.end}${w.kind==='pie'?' · Son ay':''}`,{x,y:1.38,w:width,h:.18,fontSize:9,color:'66758B',margin:0});const data=w.kind==='pie'?[{name:w.title,labels:ss.map(s=>s.name),values:ss.map(s=>s.points.at(-1).value)}]:ss.map(s=>({name:s.name,labels:s.points.map(p=>monthText(p.date)),values:s.points.map(p=>p.value)}));sl.addChart(w.kind==='line'?ppt.ChartType.line:w.kind==='pie'?ppt.ChartType.pie:ppt.ChartType.bar,data,{x,y:chartY,w:width,h:chartH,barDir:w.kind==='bar'?'bar':'col',catAxisLabelFontSize:9,chartArea:{fill:{color:'FFFFFF'},border:{color:'FFFFFF',pt:0}},valGridLine:{color:'E5EAF2',width:1},valAxisLabelFontSize:9,showLegend:true,legendPos:'b',legendFontSize:9,showValue:w.kind!=='pie',showPercent:w.kind==='pie',showLabel:false,showTitle:false,chartColors:colors,showMarker:w.kind==='line',markerSize:4,lineSize:2,showCatName:false,showSerName:false,dataLabelFormatCode:w.kind==='pie'?'0.##%':'0.##',valAxisLabelFormatCode:'0.##',dataLabelColor:'17243B',dataLabelPosition:w.kind==='pie'?'bestFit':'t',dataLabelBkgrdColor:'FFFFFF',showBorder:false,showLine:false,showCatName:false,showTitle:false,displayBlanksAs:'gap'});if(has){const td=tableData(w),fs=dual?7:9;sl.addTable([td.header,...td.rows],{x,y:4.1,w:width,h:1.65,fontSize:fs,color:'17243B',border:{type:'solid',pt:.4,color:'E5EAF2'},margin:.035,rowH:Math.min(.22,1.6/(td.rows.length+1)),colW:[width*.32,...Array(td.header.length-1).fill(width*.68/(td.header.length-1))],fill:'F8FAFF',autoPage:false,bold:false});}});sl.addText(s.comment,{x:.65,y:6.13,w:12.05,h:.65,fontSize:12,color:'17243B',margin:0,fit:'shrink'});sl.addShape(ppt.ShapeType.line,{x:.65,y:6.97,w:12.05,h:0,line:{color:'E5EAF2',width:1}});sl.addText((ctx.dataset.demo?'DEMO · Sentetik veri · ':'')+s.source+(s.note?' · '+s.note:''),{x:.65,y:7.09,w:11.5,h:.2,fontSize:8,color:'66758B',margin:0});sl.addText(String(index+1),{x:12.3,y:7.09,w:.4,h:.2,fontSize:9,color:'66758B',align:'right',margin:0});if(ctx.dataset.demo)sl.addNotes('DEMO: Tüm değerler sentetiktir; gerçek sektör verisi değildir.');});await ppt.writeFile({fileName:downloadName('pptx')});message='PowerPoint indirildi. Grafikler, gömülü verileri, tablolar ve metinler PowerPoint içinde düzenlenebilir.';}catch(e){message='PowerPoint oluşturulamadı: '+e.message;}finally{busy=false;rerender();}}

// PDF uses high-resolution slide canvases; Turkish glyphs use the browser font.
function canvasText(g,text,x,y,width,size,color='#17243b',bold=false,maxLines=3){
 g.fillStyle=color;g.font=`${bold?'700':'400'} ${size}px Arial, sans-serif`;g.textBaseline='top';
 const lines=[];for(const part of String(text||'').split('\n')){let line='';for(const word of part.split(/\s+/)){if(g.measureText(line+(line?' ':'')+word).width>width&&line){lines.push(line);line=word;}else line+=(line?' ':'')+word;}lines.push(line);}
 lines.slice(0,maxLines).forEach((line,i)=>{if(i===maxLines-1&&lines.length>maxLines)line+='…';g.fillText(line,x,y+i*size*1.22,width);});return Math.min(lines.length,maxLines)*size*1.22;
}
async function chartImage(w,width,height){let svg=visual(w).split('</svg>')[0]+'</svg>';if(w.kind!=='pie'){const correction=(height/270)/(width/640);svg=svg.replace(/<text([^>]*)>(.*?)<\/text>/g,(full,attrs,text)=>{const x=attrs.match(/\bx="([^"]+)"/)[1],y=attrs.match(/\by="([^"]+)"/)[1];return `<g transform="translate(${x} ${y}) scale(${correction} 1)"><text${attrs.replace(/\bx="[^"]+"/,'x="0"').replace(/\by="[^"]+"/,'y="0"')}>${text}</text></g>`;});}const blob=new Blob([svg.replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" width="1280" height="540" style="font-family:Arial,sans-serif" ')],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Grafik PDF için çizilemedi.'));img.src=url;});}finally{URL.revokeObjectURL(url);}}
async function pdfSlide(s,index){
 const c=document.createElement('canvas');c.width=1920;c.height=1080;const g=c.getContext('2d');g.fillStyle='#fff';g.fillRect(0,0,c.width,c.height);
 g.fillStyle='#245de8';g.fillRect(65,65,10,100);canvasText(g,s.title||'Sektör görünümü',100,62,1530,36,'#17243b',true,2);canvasText(g,'InsightBase',1648,65,210,19,'#245de8',true,1);
 for(let j=0;j<s.widgets.length;j++){const w=s.widgets[j],dual=s.layout==='double',x=dual?94+j*886:94,width=dual?842:1735,ss=series(w),h=w.table?300:550;
 canvasText(g,w.title,x,155,width,23,'#17243b',true,1);canvasText(g,`${w.mode==='ytdChange'&&w.type==='PL'?'YTD YoY':modes[w.mode]} · ${suffix(w,w.mode,ss[0].ratio)} · ${w.start} — ${w.end}${w.kind==='pie'?' · Son ay':''}`,x,199,width,14,'#66758b',false,1);
 const imageWidth=w.kind==='pie'?Math.min(width,h*640/270):width;g.drawImage(await chartImage(w,imageWidth,h),x+(width-imageWidth)/2,226,imageWidth,h);let lx=x,ly=226+h+8;
 for(let k=0;k<ss.length;k++){g.font='14px Arial, sans-serif';const label=ss[k].name,tw=Math.min(width-20,g.measureText(label).width)+28;if(lx+tw>x+width){lx=x;ly+=21;}g.fillStyle='#'+colors[k];g.fillRect(lx,ly+3,10,10);canvasText(g,label,lx+16,ly,width-(lx-x)-16,14,'#66758b',false,1);lx+=tw;}
 if(w.table){const td=tableData(w),cols=td.header.length,first=width*.32,cw=(width-first)/(cols-1),y=590,available=255,rh=available/(td.rows.length+1),fs=Math.min(dual?13:16,rh/2.7);[td.header,...td.rows].forEach((row,ri)=>{let xx=x;row.forEach((v,ci)=>{const ww=ci?cw:first;g.fillStyle=ri===0?'#eef3fc':'#f8faff';g.fillRect(xx,y+ri*rh,ww,rh);g.strokeStyle='#e5eaf2';g.lineWidth=1;g.strokeRect(xx,y+ri*rh,ww,rh);canvasText(g,v,xx+5,y+ri*rh+4,ww-10,fs,'#17243b',ri===0,ci===0?2:1);xx+=ww;});});}
 }
 canvasText(g,s.comment,94,883,1735,18,'#17243b',false,3);g.strokeStyle='#e5eaf2';g.beginPath();g.moveTo(94,1004);g.lineTo(1829,1004);g.stroke();canvasText(g,(ctx.dataset.demo?'DEMO · Sentetik veri · ':'')+s.source+(s.note?' · '+s.note:''),94,1020,1650,12,'#66758b',false,2);canvasText(g,String(index+1),1780,1020,50,13,'#66758b',false,1);return c;
}
async function exportPDF(rerender){
 if(busy)return;const errors=slides.flatMap((s,i)=>s.widgets.flatMap((w,j)=>problems(w).map(p=>`Slayt ${i+1}, grafik ${j+1}: ${p}`)));if(errors.length){message=errors.join(' ');rerender();return;}
 busy='pdf';message='';rerender();const snapshot=JSON.parse(JSON.stringify(slides));try{const pdf=new root.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:[338.67,190.5],compress:true});pdf.setProperties({title:'InsightBase Sunum',author:'InsightBase'});for(let i=0;i<snapshot.length;i++){if(i)pdf.addPage([338.67,190.5],'landscape');const c=await pdfSlide(snapshot[i],i);pdf.addImage(c.toDataURL('image/png'),'PNG',0,0,338.67,190.5,undefined,'FAST');c.width=0;c.height=0;}pdf.save(downloadName('pdf'));message='PDF indirildi. Her slayt 16:9 yatay bir sayfadır.';}catch(e){message='PDF oluşturulamadı: '+e.message;}finally{busy=false;rerender();}
}

root.InsightDeck={render,change,click,points,periods,exportDeck,exportPDF,pdfSlide,getState:()=>({slides,selected,widgetIndex}),setContext:c=>{ctx=c;},problems,tableData};
if(typeof module!=='undefined')module.exports=root.InsightDeck;
})(typeof window==='undefined'?globalThis:window);
